import React, { useState } from "react";
import './account.css';
import NavBar from "../Components/NavBar"; 
import Footer from "../Components/Footer";
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../firebase"; // Adjust import path if needed

export default function Account() {
  const [signUpData, setSignUpData] = useState({
    username: "",
    email: "",
    password: "",
    confirmPassword: ""
  });
  const [signInData, setSignInData] = useState({
    emailOrUsername: "",
    password: ""
  });
  const [error, setError] = useState("");

  // Handle signup form input changes
  const handleSignUpChange = (e) => {
    setSignUpData({...signUpData, [e.target.name]: e.target.value});
  };

  // Handle signin form input changes
  const handleSignInChange = (e) => {
    setSignInData({...signInData, [e.target.name]: e.target.value});
  };

  // Sign up submission with Firebase
  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");
    if (signUpData.password !== signUpData.confirmPassword) {
      setError("Passwords do not match.");
      return;
    }
    try {
      await createUserWithEmailAndPassword(auth, signUpData.email, signUpData.password);
      alert("Account created successfully!");
      // Ideally clear form or redirect
    } catch (err) {
      setError(err.message);
    }
  };

  // Sign in submission with Firebase
  const handleSignIn = async (e) => {
    e.preventDefault();
    setError("");
    try {
      await signInWithEmailAndPassword(auth, signInData.emailOrUsername, signInData.password);
      alert("Logged in successfully!");
      // Redirect to account or home page here if desired
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <>
      <NavBar />
      <div className="acc-page">
        <section className="account">
          <input type="checkbox" id="check" aria-hidden="true" />

          <div className="signUp">
            <form onSubmit={handleSignUp}>
              <label htmlFor="check" aria-hidden="true" className="signup">
                SignUp
              </label>
              <input
                type="text"
                name="username"
                placeholder="User Name"
                required
                value={signUpData.username}
                onChange={handleSignUpChange}
              />
              <input
                type="email"
                name="email"
                placeholder="Email"
                required
                value={signUpData.email}
                onChange={handleSignUpChange}
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                required
                value={signUpData.password}
                onChange={handleSignUpChange}
              />
              <input
                type="password"
                name="confirmPassword"
                placeholder="Confirm Password"
                required
                value={signUpData.confirmPassword}
                onChange={handleSignUpChange}
              />
              <button type="submit">Sign Up</button>
              {error && <p style={{color:"yellow", textAlign:"center"}}>{error}</p>}
            </form>
          </div>

          <div className="signIn">
            <form onSubmit={handleSignIn}>
              <label htmlFor="check" aria-hidden="true">
                SignIn
              </label>
              <input
                type="email"
                name="emailOrUsername"
                placeholder="Email or User Name"
                id="username"
                required
                value={signInData.emailOrUsername}
                onChange={handleSignInChange}
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                id="password"
                required
                value={signInData.password}
                onChange={handleSignInChange}
              />
              <button type="submit">Sign In</button>
              <p><a href="#">Forget account?</a></p>
              {error && <p style={{color:"yellow", textAlign:"center"}}>{error}</p>}
            </form>
          </div>
        </section>
      </div>
      <Footer />
    </>
  );
}
